<?php
namespace App\Support;
use App\Models\{User,Apprentice,LearningTask,TrainingSession,TrainingTopic,Qualification};
use Carbon\Carbon;
class CentreOversight {
 public static function period(string $from,string $to):void {validator(compact('from','to'),['from'=>'required|date_format:Y-m-d|before_or_equal:today','to'=>'required|date_format:Y-m-d|after_or_equal:from|before_or_equal:today'])->validate();if(Carbon::parse($from)->diffInDays(Carbon::parse($to))>=93){CentrePlanning::fail('Use an attendance interval up to93 inclusive days.');}}
 public static function ownerSlots(User $u,Apprentice $a,string $area):array {
  $u=User::find($u->id);if(!$u||!$u->active||AccountLifecycle::blocked($u)){return [];}$out=[];
  if(in_array($area,['training','attendance','reviews'],true)&&LearningAccess::tutor($u,$a)){$out[]='tutor';}
  if($area==='reviews'&&StaffDuties::assigned($u,$a,'mentor')){$out[]='mentor';}
  if($area==='functional_skills'){foreach(['maths','english']as$s){if(StaffDuties::assigned($u,$a,$s.'_tutor')){$out[]=$s.'_tutor';}}}return $out;
 }
 public static function canView(User $u,Apprentice $a,string $area):bool {return in_array($area,array_diff(array_keys(CentreManagerAccess::AREAS),['coordination']),true)&&(CentreManagerAccess::allows($u,$a,$area)||self::ownerSlots($u,$a,$area)!==[]);}
 public static function position(User $actor,Apprentice $person,string $area,string $from,string $to):array {
  $u=PortalActions::actor($actor);$a=Apprentice::findOrFail($person->id);abort_unless(self::canView($u,$a,$area),403);self::period($from,$to);$flags=[];$data=[];$proof=[];
  $add=function(string $key,string $text)use(&$flags){$flags[$key]=['key'=>$key,'text'=>$text];};
  if($area==='training'){
   $tasks=LearningTask::where('apprentice_id',$a->id)->orderBy('id')->limit(501)->get(['id','reference','status','template','due_date','submitted_at','version']);
   $count=LearningTask::where('apprentice_id',$a->id)->count();$counts=['loaded_tasks'=>$count,'approved'=>0,'awaiting_marking'=>0,'overdue_work'=>0,'marking_overdue'=>0,'source_pending'=>0,'source_checks'=>0];
   foreach($tasks as$t){$proof[]=$t->only(['id','status','version','due_date','submitted_at'])+['kind'=>$t->template['kind']??'source-pending'];if(($t->template['kind']??'source-pending')==='source-pending'){$counts['source_pending']++;continue;}if(($t->editable()&&!$t->due_date)||($t->status==='Awaiting marking'&&(!$t->submitted_at||$t->submitted_at->gt(now())))||!in_array($t->status,['Draft','Referred','Approved','Awaiting marking'],true)){$counts['source_checks']++;}if($t->status==='Approved'){$counts['approved']++;}if($t->status==='Awaiting marking'){$counts['awaiting_marking']++;if($t->markingOverdue()){$counts['marking_overdue']++;}}if($t->editable()&&$t->due_date?->lt(today())){$counts['overdue_work']++;}}
   if($count>500){$data=['source_check'=>'More than500 tasks; summary withheld for a source review.'];$add('training_source','Training source needs review');}else{$data=$counts;if($counts['source_pending']||$counts['source_checks']){$add('training_source','Task sources, dates or status need checking');}if($counts['overdue_work']){$add('task_deadline','Known-source work is past its recorded deadline');}if($counts['marking_overdue']){$add('marking_backlog','Submitted work is past the seven-day marking reference');}}
  }elseif($area==='attendance'){
   $sessions=TrainingSession::with(['marks'=>fn($q)=>$q->where('apprentice_id',$a->id)])->where(fn($q)=>$q->whereJsonContains('members',$a->id)->orWhereJsonContains('members',(string)$a->id))->whereDate('session_date','>=',$from)->whereDate('session_date','<=',$to)->orderBy('id')->limit(201)->get();$rows=[];$bad=$sessions->count()>200;
   foreach($sessions as$s){$roster=RegisterFollowup::roster($s);$m=$s->marks->first();$proof[]=['id'=>$s->id,'version'=>$s->version,'members'=>$s->members,'state'=>$s->state,'date'=>$s->session_date->toDateString(),'start'=>$s->start_time,'end'=>$s->end_time,'mark'=>$m?->only(['id','code','version','otj_confirmed','otj_minutes'])];if(!$roster['shape']||$roster['duplicates']){$bad=true;continue;}if(!$s->ended()){continue;}$rows[]=['date'=>$s->session_date->toDateString(),'code'=>$m?->code,'cancelled'=>$s->state==='Cancelled','minutes'=>0];}
   $report=AttendanceMath::report($rows);if($bad){$report=null;$add('attendance_source','Attendance source needs checking; percentage withheld');}elseif($report['unmarked']){$add('attendance_source','Attendance marks are missing or unknown');}if($report&&$report['pairs']){$add('attendance_gap','Two complete consecutive weeks have recorded non-attendance');}$data=['from'=>$from,'to'=>$to,'attendance'=>$report];
   $sourceCount=TrainingSession::where(fn($q)=>$q->whereJsonContains('members',$a->id)->orWhereJsonContains('members',(string)$a->id))->count()+\App\Models\ExtraTraining::where('apprentice_id',$a->id)->count()+\App\Models\HistoricalOtjRecord::where('apprentice_id',$a->id)->count();$stringRoster=TrainingSession::whereJsonContains('members',(string)$a->id)->exists();
   if($sourceCount>500||$stringRoster){$data['otj']=['source_check'=>$sourceCount>500?'More than500 OTJ source records; summary withheld':'Saved roster representation needs a source check; OTJ summary withheld'];$add('otj_source','Recorded OTJ source needs review');$proof=['registers'=>$proof,'source_count'=>$sourceCount,'string_roster'=>$stringRoster];}
   else{$otj=OtjPosition::forApprentice($a);$safe=collect($otj['summary'])->only(['recorded_minutes','pending_sources','invalid_sources','target_hours','planned_due_hours','recorded_percent','loaded_record_gap_hours','historical_completeness','pace_basis'])->all();$data['otj']=$safe;if($safe['pending_sources']||$safe['invalid_sources']||$safe['target_hours']===null){$add('otj_source','Recorded OTJ sources or approved plan need checking');}if(($safe['loaded_record_gap_hours']??0)>0){$add('otj_gap','Loaded recorded OTJ is below ended-block planned hours');}$proof=['registers'=>$proof,'otj'=>$safe,'otj_rows'=>array_map(fn($r)=>collect($r)->only(['kind','id','date','minutes','state','source_version'])->all(),$otj['rows'])];}
  }elseif($area==='reviews'){
   $p=ReviewReminders::position($a);$cycle=collect($p['cycle'])->only(['confirmed_count','integrity_checks','last_meeting','next_due','status','first_review_reference','basis','history_completeness'])->all();$data=['programme_status'=>$p['programme_check']?'Unknown / source check':$p['programme_status'],'paused'=>$p['paused'],'cycle'=>$cycle];$proof=$data;
   if($p['programme_check']||(!$p['paused']&&!$cycle['next_due'])||$cycle['integrity_checks']){$add('review_history','Review history or programme status needs checking');}elseif($p['due']){$add('review_due','Review due reference from checked signed-copy history');}
  }elseif($area==='functional_skills'){
   $subjects=CentreManagerAccess::allows($u,$a,$area)?['maths','english']:array_map(fn($slot)=>str_replace('_tutor','',$slot),self::ownerSlots($u,$a,$area));$data=[];
   foreach($subjects as$subject){$topics=TrainingTopic::where('apprentice_id',$a->id)->where('subject',$subject)->orderBy('id')->get(['id','status','evidence_stage','planned_hours','version']);$qualifications=Qualification::where('apprentice_id',$a->id)->where('subject',$subject)->orderBy('id')->get(['id','subject','type','level','status','start_date','achievement_date','version']);$q=$qualifications->map(fn($v)=>$v->only(['id','type','level','status'])+['position'=>$v->position()])->all();$data[$subject]=['assigned_topics'=>$topics->count(),'completed_topics'=>$topics->where('status','Completed')->count(),'awaiting_topic_review'=>$topics->where('evidence_stage','Awaiting review')->count(),'planned_topic_hours'=>(float)$topics->sum('planned_hours'),'qualifications'=>$q,'meaning'=>'Assigned topic completion is separate from qualification achievement; no main-aim OTJ is added'];$proof[$subject]=['topics'=>$topics->map->getAttributes()->all(),'qualifications'=>$qualifications->map->getAttributes()->all()];
    $check=$topics->where('evidence_stage','Awaiting review')->isNotEmpty()||collect($q)->contains(fn($row)=>in_array($row['position'],['Overdue','Date check'],true)||$row['status']==='Awaiting confirmation')||(!$topics->count()&&!$qualifications->count()&&$a->{$subject.'_tutor_id'});
    if($check){$add($subject.'_followup',ucfirst($subject).' training/results need a source follow-up');}
   }
  }
  return ['area'=>$area,'identity'=>$a->only(['id','reference','first_name','last_name','tutor_group_id']),'captured_at'=>now()->toIso8601String(),'data'=>$data,'flags'=>$flags,'source_hash'=>ReviewedImports::hash(['date'=>today()->toDateString(),'area'=>$area,'period'=>[$from,$to],'apprentice'=>$a->only(['id','version','tutor_group_id','tutor_id','mentor_id','maths_tutor_id','english_tutor_id']),'proof'=>$proof,'flags'=>$flags]),'private_support_or_evidence_included'=>false];
 }
 public static function owners(Apprentice $a,string $area,string $flag):array {
  $slots=match($area){'training','attendance'=>['tutor'],'reviews'=>['tutor','mentor'],'functional_skills'=>str_starts_with($flag,'maths_')?['maths_tutor']:['english_tutor'],default=>[]};$out=[];
  foreach($slots as$slot){$u=$a->{$slot.'_id'}?User::find($a->{$slot.'_id'}):null;if($u&&in_array($slot,self::ownerSlots($u,$a,$area),true)){$out[]=['id'=>$u->id,'name'=>$u->name,'slot'=>$slot];}}return $out;
 }
}
